import {
  readStudentCode,
  assertVarKeyword,
  assertBindingValue,
} from '/lab-test-helpers.js';

const code = readStudentCode('/App.js');

test('declara favoriteFood com var', () => {
  assertVarKeyword(code, 'var', 'favoriteFood');
});

test('favoriteFood é pizza', async () => {
  await assertBindingValue('favoriteFood', 'pizza', { type: 'string' });
});

